// One item per new A1b request (reminders send no audio). The worker serves voice.m4a against the
// timing job's media token (D-071). Replace the base URL on import.
// The video's own worker (D-074); WORKER is the fallback filled in on deploy.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && parse(item.json.voice)?.file);
return rows.map(({ json: row }) => {
  const voice = parse(row.voice);
  const shortId = String(row.video_id).slice(0, 8);
  return {
    json: {
      url: `${row.worker_url || WORKER}/media/${row.video_id}/${row.version}/${voice.file.job_id}/voice.m4a?t=${voice.file.token}`,
      caption: `🎙 #${shortId} v${row.version} · giọng đọc lần ${row.take}/${voice.max_takes}`,
    },
  };
});

// One message with buttons per row from voice_approvals_due(), after its audio (Vietnamese, D-061).
// Callback data: a1b:<A|G|R>:<32-hex token>. Đọc lại pays for one more TTS take; its label shows the
// estimate (none after the last take: the video then needs a decision).
// Shared Telegram formatting (same in every approval message node): the text goes out as HTML,
// times in Vietnam time (UTC+7, no daylight saving), and the request token rides in a hidden link
// at the start, so a reply to the message finds its request (WF-06) without showing the token.
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const hiddenRef = (kind, token) => `<a href="https://t.me/?${kind}=${token}">\u200d</a>`;
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, '0')}`;
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const voice = parse(row.voice) ?? {};
  const cost = voice.retake_cost ? `${voice.retake_cost.amount} ${voice.retake_cost.currency}` : null;
  const reminder = row.kind === 'REMINDER';
  const length = typeof voice.seconds === 'number' ? ` · ${clock(voice.seconds)}` : '';
  const html = [
    `<b>${reminder ? '⏰ Nhắc: ' : ''}🎙 Duyệt giọng đọc</b> · bước 2/5 · A1b`,
    `«${esc(row.title ?? '?')}»`,
    `#${shortId} v${row.version} · lần ${row.take}/${voice.max_takes ?? '?'}${length} · Duyệt → Claude viết code tập`,
    cost ? `Đọc lại: đọc lại toàn bộ, ≈ ${esc(cost)}` : 'Hết lượt đọc lại: bấm Đọc lại thì video chờ bạn quyết định',
    `⏰ Hạn ${vnTime(row.expires_at)}`,
  ].join('\n');
  return {
    json: {
      html,
      retakeLabel: cost ? `Đọc lại (~${cost})` : 'Đọc lại (hết lượt)',
      approve: `a1b:A:${row.token}`,
      retake: `a1b:G:${row.token}`,
      reject: `a1b:R:${row.token}`,
    },
  };
});
